KB = [
 ("service", "Quiénes somos",
  "DIAMANE es una casa de diamantes de Morelia, Michoacán: vende diamantes sueltos naturales y de laboratorio, con su certificado, a joyeros y talleres (mayoreo). Es parte del mismo grupo que Anello (joyería al público, https://www.anello.mx). Sitio: https://www.diamane.mx (la tienda en línea es solo para joyeros registrados). Correo hola@diamane.mx."),
 ("policy", "Solo joyeros",
  "DIAMANE vende únicamente a joyeros, talleres y negocios de joyería. A una persona que busca una joya o un diamante para ella o para regalar se le recomienda Anello (https://www.anello.mx, WhatsApp 443 324 4511), que vende al público."),
 ("policy", "Verificación de joyeros",
  "Como DIAMANE vende a precio de mayoreo solo a joyeros, antes de dar precios o vender se verifica cada negocio UNA sola vez con su Constancia de Situación Fiscal del SAT (se descarga en sat.gob.mx o en la app SAT Móvil): su actividad económica debe ser de joyería, orfebrería, relojería o piedras y metales preciosos. La revisa una persona del equipo y se le avisa por WhatsApp. La misma constancia sirve para su factura. Ya verificado, también puede entrar a la tienda en línea de diamane.mx."),
 ("policy", "Precios",
  "Los precios son de mayoreo para joyería y se dan MÁS IVA (16 %). Diamantes naturales: se basan en la lista Rapaport del mercado, con un descuento según el tamaño de la piedra, en pesos al tipo de cambio del día; por eso pueden moverse un poco cada semana. Diamantes de laboratorio y acentos tienen su propio precio. El precio vigente es el que dan las herramientas; nunca lo inventes ni ofrezcas descuentos."),
 ("service", "Certificados",
  "Las piedras traen certificado DIAMANE y muchas además de un laboratorio internacional (GIA, IGI u otros); el que tiene cada una sale en sus datos. Muchas piedras de DIAMANE tienen certificado ICERT: tarjeta con chip NFC que, al acercarla al celular, muestra el reporte de la piedra y permite verificar que es auténtica."),
 ("faq", "Abreviaturas de forma",
  "BR redondo brillante, PR princesa, OV oval, EM esmeralda, PS pera, MQ marquesa, CU cojín, AC asscher, RA radiant, HS corazón, BG baguette, TR trillón. En el nombre de cada piedra va la forma, los quilates, la pureza y el color, por ejemplo «Diamante BR 0.41 VS2 L»."),
 ("policy", "Formas de pago",
  "Sin pedido mínimo: se puede comprar una sola piedra. Formas de pago: 1) En línea con tarjeta, con la liga o el QR de la cotización (Mercado Pago); ahí puede pagar el total o solo el anticipo y el pedido se confirma solo. 2) Transferencia o depósito: {DATOS_TRANSFERENCIA}; después manda su comprobante por este WhatsApp. 3) Efectivo en la oficina de DIAMANE, Felipe de Jesús Tena 31, Morelia (avisa al equipo el día y la hora con avisar_a_la_tienda). 4) En dólares, al tipo de cambio del día. No manejamos crédito."),
 ("policy", "Apartado",
  "Una piedra se aparta con el 10 % del total (IVA incluido) y queda apartada 30 días para liquidar. Si en 30 días no se liquida, la piedra se libera y el 10 % queda como saldo a favor del joyero para otra piedra (no se pierde). La cotización por sí sola no aparta nada."),
 ("policy", "Entrega y envíos",
  "Tres opciones: recoger en la oficina de DIAMANE en Morelia; envío por paquetería asegurada, que paga el joyero (el equipo le confirma el costo con su dirección y código postal); o entrega en persona por alguien del equipo. La piedra se entrega o se envía ya liquidada."),
 ("policy", "Factura, crédito y consignación",
  "Sí facturamos: pide su constancia de situación fiscal (o RFC, razón social, código postal, régimen fiscal y uso del CFDI) y pásala al equipo con avisar_a_la_tienda. No manejamos crédito. Sí trabajamos a consignación con joyeros: eso lo platica una persona del equipo (pasar_a_humano)."),
 ("policy", "Videollamada",
  "Se puede agendar una videollamada con DIAMANE para ver las piedras en vivo y resolver dudas; se agenda con ver_horarios_demo / agendar_demo y la liga sale al agendar."),
]
